class Solution {
    public int fillCups(int[] amount){
        int sum=amount[0]+amount[1]+amount[2],maximum=Math.max(amount[0],Math.max(amount[1],amount[2]));
        return Math.max(maximum,(sum+1)/2);
    }
}

